311		void	read_raw_state(void) {
312			// {{{
313			m_state.m_valid = false;
314			for(int i=0; i<16; i++)
315				m_state.m_sR[i] = cmd_read(i);
316			for(int i=0; i<16; i++)
317				m_state.m_uR[i] = cmd_read(i+16);
318	#ifdef	ZIPSYSTEM
319			for(int i=0; i<20; i++)
320				m_state.m_p[i]  = cmd_read(i+32);
321	#endif
322	
323			m_state.m_gie = wb_read(CMD_REG) & CMD_GIE;
324			m_state.m_pc  = (m_state.m_gie) ? (m_state.m_uR[15]):(m_state.m_sR[15]);
325			m_state.m_sp  = (m_state.m_gie) ? (m_state.m_uR[13]):(m_state.m_sR[13]);
326	
327			if (m_state.m_last_pc_valid)
328				m_state.m_imem[0].m_a = m_state.m_last_pc;
329			else
330				m_state.m_imem[0].m_a = m_state.m_pc - 1;
331			m_state.m_imem[0].m_d = m_mem[m_state.m_imem[0].m_a & 0x0fffff];
332			m_state.m_imem[0].m_valid = ((m_state.m_imem[0].m_a & 0xfff00000)==0x00100000);
333			m_state.m_imem[1].m_a = m_state.m_pc;
334			m_state.m_imem[1].m_valid = ((m_state.m_imem[1].m_a & 0xfff00000)==0x00100000);
335			m_state.m_imem[1].m_d = m_mem[m_state.m_imem[1].m_a & 0x0fffff];
336	
337			for(int i=1; i<4; i++) {
338				// {{{
339				if (!m_state.m_imem[i].m_valid) {
340					m_state.m_imem[i+1].m_valid = false;
341					m_state.m_imem[i+1].m_a = m_state.m_imem[i].m_a+1;
342					continue;
343				}
344				m_state.m_imem[i+1].m_a = zop_early_branch(
345						m_state.m_imem[i].m_a,
346						m_state.m_imem[i].m_d);
347				m_state.m_imem[i+1].m_d = m_mem[m_state.m_imem[i].m_a & 0x0fffff];
348				m_state.m_imem[i+1].m_valid = ((m_state.m_imem[i].m_a&0xfff00000)==0x00100000);
349				// }}}
350			}
351	
352			m_state.m_smem[0].m_a = m_state.m_sp;
353			for(int i=1; i<5; i++)
354				m_state.m_smem[i].m_a = m_state.m_smem[i-1].m_a+1;
355			for(int i=0; i<5; i++) {
356				m_state.m_smem[i].m_valid =
357					(m_state.m_imem[i].m_a > 0x10000);
358				m_state.m_smem[i].m_d = m_mem[m_state.m_imem[i].m_a & 0x0fffff];
359			}
360			m_state.m_valid = true;
361			// }}}
362		}
363	
364		void	read_raw_state_cheating(void) {
365			// {{{
366			m_state.m_valid = false;
367			for(int i=0; i<16; i++)
368				m_state.m_sR[i] = m_core->cpu_regs[i];
369			m_state.m_sR[14] = (m_state.m_sR[14]&0xffffe000)|m_core->w_iflags;
370			m_state.m_sR[15] = m_core->cpu_ipc;
371			for(int i=0; i<16; i++)
372				m_state.m_uR[i] = m_core->cpu_regs[i+16];
373			m_state.m_uR[14] = (m_state.m_uR[14]&0xffffe000)|m_core->w_uflags;
374			m_state.m_uR[15] = m_core->cpu_upc;
375	
376			m_state.m_gie = m_core->r_gie;
377			m_state.m_pc  = (m_state.m_gie) ? (m_state.m_uR[15]):(m_state.m_sR[15]);
378			m_state.m_sp  = (m_state.m_gie) ? (m_state.m_uR[13]):(m_state.m_sR[13]);
379	
380	#ifdef	ZIPSYSTEM
381			// {{{
382			m_state.m_p[0] = m_core->pic_data;
383			m_state.m_p[1] = m_core->watchdog;
384			if (!m_show_user_timers) {
385				m_state.m_p[2] = m_core->watchbus;
386			} else {
387				// The last bus error address
388				m_state.m_p[2] = m_core->wdbus_data;
389			}
390	
391			m_state.m_p[3] = m_core->alt_int_state;
392			m_state.m_p[4] = m_core->timer_a;
393			m_state.m_p[5] = m_core->timer_b;
394			m_state.m_p[6] = m_core->timer_c;
395			m_state.m_p[7] = m_core->jiffies;
396	
397			m_state.m_p[ 8] = m_core->utc_data;
398			m_state.m_p[ 9] = m_core->uoc_data;
399			m_state.m_p[10] = m_core->upc_data;
400			m_state.m_p[11] = m_core->uic_data;
401	
402			m_state.m_p[12] = m_core->mtc_data;
403			m_state.m_p[13] = m_core->moc_data;
404			m_state.m_p[14] = m_core->mpc_data;
405			m_state.m_p[15] = m_core->mic_data;
406			// }}}
407	#endif
408			// }}}
409		}
