443		void	showreg(int y, int x, const char *n, int r, bool c) {
444			// {{{
445			if (r < 16)
446				dispreg(y, x, n, m_state.m_sR[r], c);
447			else
448				dispreg(y, x, n, m_state.m_uR[r-16], c);
449			move(y,x+17);
450	
451	#ifdef	OPT_PIPELINED
452			addch( ((r == (int)(dcd_Aid()&0x01f))&&(m_core->dcd_valid)
453					&&(m_core->dcd_rA))
454				?'a':((c)?'<':' '));
455			addch( ((r == (int)(dcd_Bid()&0x01f))&&(m_core->dcd_valid)
456					&&(m_core->dcd_rB))
457				?'b':' ');
458			addch( ((r == m_core->wr_reg_id)
459					&&(m_core->wr_reg_ce))
460				?'W':' ');
461	#else
462			addch( ((r == m_core->wr_reg_id)
463					&&(m_core->wr_reg_ce))
464				?'W':((c)?'<':' '));
465	#endif
466			// }}}
467		}
