469		void	showins(int y, const char *lbl, const int ce, const int valid,
470				const int gie, const int stall, const unsigned int pc,
471				const bool phase) {
472			// {{{
473			char	la[80], lb[80];
474			unsigned iv = m_mem[pc >> 2];
475			bool	cisw = (iv & 0x80000000)?true:false;
476	
477			if (ce)
478				mvprintw(y, 0, "Ck ");
479			else
480				mvprintw(y, 0, "   ");
481			if (stall)
482				printw("Stl ");
483			else
484				printw("    ");
485			printw("%s%c 0x%08x", lbl, ((cisw)&&(phase))?'/':':', pc);
486	
487			if (valid) {
488				if (gie) attroff(A_BOLD);
489				else	attron(A_BOLD);
490				zipi_to_double_string(pc, iv, la, lb);
491				if ((!cisw)||(phase))
492					printw("  %-24s", la);
493				else
494					printw("  %-24s", lb);
495			} else {
496				attroff(A_BOLD);
497				printw("  (0x%08x)%28s", iv,"");
498			}
499			attroff(A_BOLD);
500			// }}}
501		}
