503		void	dbgins(const char *lbl, const int ce, const int valid,
504				const int gie, const int stall, const unsigned int pc,
505				const bool phase, const bool illegal) {
506			// {{{
507			char	la[80], lb[80];
508	
509			if (!m_dbgfp)
510				return;
511	
512			if (ce)
513				fprintf(m_dbgfp, "%s Ck ", lbl);
514			else
515				fprintf(m_dbgfp, "%s    ", lbl);
516			if (stall)
517				fprintf(m_dbgfp, "Stl ");
518			else
519				fprintf(m_dbgfp, "    ");
520			fprintf(m_dbgfp, "0x%08x%s:  ", pc, (phase)?"/P":"  ");
521	
522			if (valid) {
523				zipi_to_double_string(pc, m_mem[pc>>2], la, lb);
524				if ((phase)||((m_mem[pc>>2]&0x80000000)==0))
525					fprintf(m_dbgfp, "  %-24s", la);
526				else
527					fprintf(m_dbgfp, "  %-24s", lb);
528			} else {
529				fprintf(m_dbgfp, "  (0x%08x)", m_mem[pc]);
530			} if (illegal)
531				fprintf(m_dbgfp, " (Illegal)");
532			fprintf(m_dbgfp, "\n");
533			// }}}
534		}
