536		void	show_state(void) {
537			// {{{
538			int	ln= 0;
539	
540			read_raw_state_cheating();
541	
542			mvprintw(ln,0, "Peripherals-SS"); ln++;
543			printw(" %s",
544				// (m_core->pf_illegal)?"PI":"  ",
545				(m_core->dcd_illegal)?"DI":"  "
546				);
547	
548	#ifdef	OPT_EARLY_BRANCHING
