2363				} else
2364					chv = getch();
2365	
2366				switch(chv) {
2367				// {{{
2368				case 'h': case 'H':
2369					tb->wb_write(CMD_REG, CMD_HALT|CMD_CATCH);
2370					if (!halted)
2371						erase();
2372					halted = true;
2373					break;
2374				case 'G':
2375					high_speed = true;
2376					// cbreak();
2377				case 'g':
2378					tb->wb_write(CMD_REG, CMD_GO|CMD_CATCH);
2379					if (halted)
2380						erase();
2381					halted = false;
2382					manual = false;
2383					break;
2384				case 'm':
2385					tb->show_user_timers(false);
2386					break;
2387				case 'q': case 'Q':
2388					done = true;
2389					break;
2390				case 'r': case 'R':
2391					if (manual)
2392						tb->reset();
2393					else
2394						tb->wb_write(CMD_REG, CMD_RESET|CMD_HALT|CMD_CATCH);
2395					halted = true;
2396					erase();
2397					break;
2398				case 's':
2399					if (!halted)
2400						erase();
2401					tb->step();
2402					manual = false;
2403					halted = true;
2404					// if (high_speed)
2405						// halfdelay(1);
2406					high_speed = false;
2407					break;
2408				case 'S':
2409					if ((!manual)||(halted))
2410						erase();
2411					manual = true;
2412					halted = true;
2413					// if (high_speed)
2414						// halfdelay(1);
2415					high_speed = false;
2416					tb->m_core->cpu_halt = 0;
2417					tb->m_core->cmd_step = 1;
2418					tb->eval();
2419					tb->tick();
