69	class	SIMDEV {
70	public:
71		virtual	uint32_t	lw(uint32_t addr) = 0;
72		virtual void	sw(uint32_t addr, uint32_t vl) = 0;
73	
74		virtual	uint32_t	lb(uint32_t addr) {
75			uint32_t v = lw(addr&-4);
76	
77			// fprintf(stderr, "\tLH(%08x) -> %08x", addr, v);
78			v >>= (8*(3-(addr&3)));
79			// fprintf(stderr, " -> %08x", v);
80			v &= 0x0ff;
81			// fprintf(stderr, " -> %02x\n", v);
82			return v;
83		}
84		virtual	uint32_t	lh(uint32_t addr) {
85			uint32_t v = lw(addr&-4);
86	
87			// fprintf(stderr, "\tLH(%08x) -> %08x", addr, v);
88			if ((addr&2)==0)
89				v >>= 16;
90			// fprintf(stderr, " -> %08x", v);
91			v &= 0x0ffff;
92			// fprintf(stderr, " -> %04x\n", v);
93			return v;
94		}
95	
96		virtual void sh(uint32_t addr, uint32_t vl) {
97			uint32_t v = (vl & 0x0ffff);
98			v = v | (v<<16);
99			sw(addr, v);
100		}
101	
102		virtual void sb(uint32_t addr, uint32_t vl) {
103			uint32_t v = (vl & 0x0ff);
104			v = v | (v<<16);
105			v = v | (v<<8);
106			sw(addr, v);
107		}
108	
109		virtual	bool	interrupt(void) { return false; };
110		virtual	void	tick(void) {};
111	
112		virtual	void	load(uint32_t addr, const char *buf, size_t ln) {}
113	};
114	
115	class	UARTDEV : public SIMDEV {
116		uint32_t	m_setup;
117		bool		m_debug;
118	public:
119		UARTDEV(void) { m_setup = 868; m_debug = false; }
120	
121		virtual	uint32_t	lw(uint32_t addr) {
122			switch(addr&0x0c) {
123			case  0: return m_setup;
124			case  4: return 0;
125			case  8: return 0x100;
126			case 12: return 0;
127			} return 0;
128		}
129			
130		virtual void sw(uint32_t addr, uint32_t vl) {
131			if (m_debug) fprintf(stderr,
132				"UART->SW(%08x, %08x)\n", addr, vl);
133			switch(addr&0x0c) {
134			case  0: m_setup = vl & 0x3fffffff; break;
135			case  4: break;
136			case  8: break;
137			case 12: putchar(vl & 0x0ff);
138			}
139		}
140	};
