226	public:
227		SIMDEV	*m_dev;
228		uint32_t m_addr, m_mask;
229		int	m_flags;
230		char	*m_name;
231	};
232	
233	class	SIMBUS {
234		bool	m_buserr;
235		std::vector<SIMENTRY *>	m_devlist;
236		int	getdev(uint32_t addr) {
237			for(size_t i=0; i<m_devlist.size(); i++)
238				if ((addr&m_devlist[i]->m_mask)==m_devlist[i]->m_addr){
239					return i;
240			}
241	
242			/*
243			fprintf(stderr, "GETDEV(0x%08x) - not found\n", addr);
244			for(size_t i=0; i<m_devlist.size(); i++) {
245				fprintf(stderr, "ADDR(0x%08x) & 0x%08x = %08x != %08x\n",
246					addr, m_devlist[i]->m_mask,
247					addr & m_devlist[i]->m_mask,
248					m_devlist[i]->m_addr);
249			} */
250	
251			return -1;
252		}
253		int	getwrdev(uint32_t addr) {
254			int	devid = getdev(addr);
255			if (0 <= devid) {
256				if (m_devlist[devid]->m_flags & W_OK)
257					return devid;
258	fprintf(stderr, "ADDRESS %08x in %s is not writable!!\n", addr, m_devlist[devid]->m_name);
259			}
260	else fprintf(stderr, "ADDRESS %08x not found\n", addr);
261			return -1;
262		}
263		int	getexdev(uint32_t addr) {
264			int	devid = getdev(addr);
265			if (0 <= devid) {
266				if (m_devlist[devid]->m_flags & X_OK)
267					return devid;
268				fprintf(stderr, "Address in %s is not executable\n", m_devlist[devid]->m_name);
269			}
270			fprintf(stderr, "ExDEV not found (0x%08x), devid = %d\n", addr, devid);
271			return -1;
272		}
273	public:
274		SIMBUS(void) { m_buserr = false; }
275		void	add(SIMDEV *dev, uint32_t addr, uint32_t mask, const char *p, const char *name = "") {
276			SIMENTRY	*s = new SIMENTRY;
277	
278			s->m_dev = dev;
279			s->m_addr= addr;
280			s->m_mask= mask;
281			s->m_name= strdup(name);
282			s->m_flags= 0;
283	
284			if ((strchr(p, 'w'))||(strchr(p, 'W')))
285				s->m_flags |= W_OK;
286			if ((strchr(p, 'r'))||(strchr(p, 'R')))
287				s->m_flags |= R_OK;
288			if ((strchr(p, 'x'))||(strchr(p, 'X')))
289				s->m_flags |= X_OK;
290			if ((strchr(p, 'l'))||(strchr(p, 'L')))
291				s->m_flags |= L_OK;
292			m_devlist.push_back(s);
293		}
294	
295		uint32_t	lb(uint32_t addr) {
296			int	devid;
297			if (0 <= (devid = getdev(addr)))
298				return m_devlist[devid]->m_dev->lb(addr & (~m_devlist[devid]->m_mask));
299			m_buserr = true;
300			return 0;
301		}
302		uint32_t	lh(uint32_t addr) {
303			int	devid;
304			if (0 <= (devid = getdev(addr)))
305				return m_devlist[devid]->m_dev->lh(addr & ((~m_devlist[devid]->m_mask)&-2));
306			m_buserr = true;
307			return 0;
308		}
309		uint32_t	lw(uint32_t addr) {
310			int	devid;
311			if (0 <= (devid = getdev(addr)))
312				return m_devlist[devid]->m_dev->lw(addr & ((~m_devlist[devid]->m_mask)&-4));
313			m_buserr = true;
314			return 0;
315		}
316		uint32_t	lx(uint32_t addr) {
317			int	devid;
318			if (0 <= (devid = getexdev(addr)))
319				return m_devlist[devid]->m_dev->lw(addr & ((~m_devlist[devid]->m_mask)&-4));
320			m_buserr = true;
321			return 0;
322		}
323		void	sb(uint32_t addr, uint32_t vl) {
324			int	devid;
325			if (0 <= (devid = getwrdev(addr))) {
326				return m_devlist[devid]->m_dev->sb(addr & (~m_devlist[devid]->m_mask), vl & 0x0ff);
327			} else {
328				fprintf(stderr, "No such address, %08x\n", addr);
329			}
330			m_buserr = true;
331			return;
332		}
333		void	sh(uint32_t addr, uint32_t vl) {
334			int	devid;
335			if (0 <= (devid = getwrdev(addr)))
336				return m_devlist[devid]->m_dev->sh(addr & -2 & (~m_devlist[devid]->m_mask), vl & 0x0ffff);
337			m_buserr = true;
338			return;
339		}
340		void	sw(uint32_t addr, uint32_t vl) {
341			int	devid;
342			if (0 <= (devid = getwrdev(addr)))
343				return m_devlist[devid]->m_dev->sw(addr & -4 & (~m_devlist[devid]->m_mask), vl);
344			m_buserr = true;
345			return;
346		}
347		bool	interrupt(void) { return false; };
348	
349		bool	error(void) {
350			bool tmp = m_buserr;
351			m_buserr = false;
352			return tmp;
353		}
354	
355		void	tick(void) {
356			for(size_t i=0; i<m_devlist.size(); i++)
357				m_devlist[i]->m_dev->tick();
358		}
359	
360		void	load(uint32_t addr, const char *data, size_t len) {
361			int	devid;
362			if ((0 <= (devid = getdev(addr)))
363					&&(m_devlist[devid]->m_flags & L_OK))
364				m_devlist[devid]->m_dev->load(
365					addr & (~m_devlist[devid]->m_mask), data, len);
366			else {
367				fprintf(stderr, "DEVID = %d\n", devid);
368				m_buserr = true;
369			} return;
370		}
371	};
