373	class	ZIPMACHINE {
374		bool		m_gie, m_jumped, m_advance_pc, m_locked;
375		int		m_lockcount;
376		unsigned long	m_icount;
377	public:
378		uint32_t	m_r[32];
379		SIMBUS		*m_bus;
380		FILE		*m_mapf;
381	
382		ZIPMACHINE(void) {
383			m_locked = false; m_lockcount = 0;
384			m_mapf = NULL;
385			m_bus = NULL;
386			m_gie = false;
387			m_jumped= m_advance_pc = false;
388			m_icount = 0;
389		}
390	
391		void dump() {
392			fflush(stderr);
393			fflush(stdout);
394			printf("ZIPM--DUMP: ");
395			if (gie())
396				printf("Interrupts-enabled\n");
397			else
398				printf("Supervisor mode\n");
399			printf("\n");
