944		void	cisinsn(uint16_t insn) {
945			uint32_t	imm;
946			int		dr, br, cisop, fullop;
947	
948			cisop = (insn >> 8) & 0x07;
949			switch(cisop) {
950			case 0: fullop =  0; break; // SUB
951			case 1: fullop =  1; break; // AND
952			case 2: fullop =  2; break; // ADD
953			case 3: fullop = 16; break; // CMP
954			case 4: fullop = 18; break; // LW
955			case 5: fullop = 19; break; // SW
956			case 6: fullop = 24; break; // LDI
957			case 7: fullop = 13; break; // MOV
958			}
959	
960			dr = (insn>>11) & 0x0f;
961	
962			if (fullop == 24) {
963				// LDI
964				imm = sbits(insn, 8) & 0x07fffff;
965				fullinsn(0x80000000 | (dr<<27) | (fullop<<22) | imm);
966			} else if (fullop == 13) {
967				// MOV
968				br = (insn >> 3) & 0x0f;
969				imm = sbits(insn, 3) & 0x01fff;
970				fullinsn(0x80000000 | (dr << 27) | (fullop<<22) | (br<<14) | imm);
971			} else if (insn & 0x80) {
972				// Uses a breg
973				br = (insn >> 3) & 0x0f;
974				imm = sbits(insn, 3) & 0x3fff;
975				fullinsn(0x80040000 | (dr << 27) | (fullop<<22) | (br<<14) | imm);
976			} else if ((fullop == 18)||(fullop == 19)) {
977				// Load or store, breg is assumed to be SP
978	// 0x04844000
979				br = 13;
980				imm = sbits(insn, 7) & 0x3fff;
981				fullinsn(0x80040000 | (dr << 27) | (fullop<<22) | (br<<14) | imm);
982			} else {
983				imm = sbits(insn, 7) & 0x03ffff;
984				fullinsn(0x80000000 | (dr << 27) | (fullop<<22) | imm);
985			}
986		}
987	
988		void	execute(uint32_t insn) {
989			/// fprintf(stderr, "EXEC-INSN(@0x%08x - %08x)\n", pc(), insn);
990			bool	igie = gie();
991			if (insn & 0x80000000) {
992				int		ibase = rbase();
993				cisinsn((insn>>16) & 0x0ffff);
994				if (m_advance_pc)
995					m_r[14+ibase] |= (CC_PHASE);
996				if ((!m_jumped)&&(igie == gie())) {
997					cisinsn(insn & 0x0ffff);
998					m_r[14+ibase] &= ~(CC_PHASE);
999				} if (m_advance_pc)
1000					pc_advance(igie);
1001				m_jumped = false;
1002			} else {
1003				m_r[14+rbase()] &= ~(CC_PHASE);
1004				fullinsn(insn);
1005	
1006				if (m_advance_pc)
1007					pc_advance(igie);
1008	
1009				if ((gie())&&(cc() & CC_STEP))
1010					gie(false);
1011			}
1012		}
1013	};
1014	
1015	int main(int argc, char **argv) {
1016		const char *executable = "a.out";
1017		SIMBUS *bus;
1018		bool	done;
1019		ZIPMACHINE	*zipm;
1020		ELFSECTION	**secpp, *secp;
1021		uint32_t	entry;
1022	
1023		if (argc > 1)
1024			executable = argv[1];
1025		if (access(executable, R_OK)!=0) {
1026			fprintf(stderr, "Cannot read %s\n", executable);
1027			exit(EXIT_FAILURE);
1028		} elfread(executable, entry, secpp);
1029		if (0 == secpp[0]->m_len) {
1030			fprintf(stderr, "Executable file has no contents!\n");
1031			exit(EXIT_FAILURE);
1032		}
1033	
1034		// Timer  at 0x0100?
1035		// Buserr at 0x0101?
1036		// Addresses are given in 32-bit glory, so they reference 8-bit bytes
1037		bus = new SIMBUS();
1038		// BUSITEM net = new NETDEV();
1039	
1040		bus->add(new UARTDEV(),  0x00000150, 0xfffffff0, "RW", "UART");// 4 words
1041		// bus->add(new SDCDEV(12), 0x00000420, 0xfffffff0, "RW");// 4 words
1042		// bus->add(net->ctrl,   0x00000440, 0xffffffe0, "RW");// 8 words
1043		// bus->add(net->data,   0x00002000, 0xffffe000, "R"); // 8 words
1044		// bus->add(net->data,   0x00003000, 0xffffe000, "R"); // 8 words
1045		bus->add(new MEMDEV(17), 0x0020000, 0x7fe0000, "RWX", "BlockRAM");// Block RAM
1046		bus->add(new ROMDEV(24),0x01000000,0xff000000, "RXL", "Flash"); // Flash
1047		bus->add(new MEMDEV(28),0x10000000,0xf0000000, "RWX", "SDRAM");// SDRAM
1048	
1049		for(int s=0; secpp[s]->m_len; s++) {
1050			secp = secpp[s];
1051			if (false) fprintf(stderr,
1052				"Attempting to LOAD->(%08x, ..., %d)\n",
1053				secp->m_start, secp->m_len);
1054			bus->load(secp->m_start, (const char *)&secp->m_data[0], secp->m_len);
1055			if (bus->error()) {
1056				fprintf(stderr, "LOAD: Error writing to mem @ 0x%08x\n", secp->m_start);
1057				// exit(EXIT_FAILURE);
1058			}
1059		}
1060	
1061		if(bus->error()) {
1062			fprintf(stderr, "ERR: Executable file doesn\'t fit in simulator\n");
1063			exit(EXIT_FAILURE);
1064		}
1065	
1066		done = false;
1067		zipm = new ZIPMACHINE;
1068		if (access("map.txt", R_OK)==0)
1069			zipm->m_mapf = fopen("map.txt","r");
1070		zipm->init(bus);
1071		zipm->m_r[15] = entry;
1072		while(!done) {
1073			uint32_t	insn;
1074			insn = bus->lx(zipm->pc());
1075	
1076			if (bus->error()) {
1077				if (zipm->gie()) {
1078					zipm->m_r[14+16] |= CC_BUSERR;
1079					zipm->gie(false);
1080					continue;
1081				} else {
1082					zipm->m_r[14] |= CC_BUSERR;
1083					fprintf(stderr, "IFetch BUSERR, %08x\n", zipm->pc());
1084					zipm->dump();
1085					exit(EXIT_FAILURE);
1086				}
1087			} else {
1088				if (!zipm->sleeping())
1089					zipm->execute(insn);
1090			}
1091	
1092			if (zipm->halted()) {
1093				fflush(stderr);
1094				fflush(stdout);
1095				printf("CPU HALT\n");
1096				done = true;
1097				break;
1098			}
1099	
1100			bus->tick();
1101			if ((bus->interrupt())&&(zipm->gie())&&(!zipm->locked())) {
1102				zipm->gie(false);
1103				zipm->sleep(false);
1104			}
1105		}
1106	}
